  const testMock=(rule:MockRule)=>{const body=rule.behavior?rule.behavior.sample.body:rule.requestBody;setRequestTemplate(null);setRequestWarnings([]);setTestError('');setTestTarget('mock');setTestMethod(rule.method);setTestPath(mockRequestPath(rule).replace(/\{[^}]+\}/g,'u_001')+(Object.keys(rule.query).length?'?'+new URLSearchParams(rule.query):''));setTestBody(body===undefined?'':pretty(body));setTestHeaders(pretty(rule.behavior?.sample.headers??rule.requestHeaders));if(rule.behavior)setTestPath(mockBasePath(rule.service)+rule.behavior.sample.path);setTestResult(null);openKind('request');};
