    const dynamic=behavior.bindings.filter(b=>b.value.kind==='uuid'||b.value.kind==='now').map(b=>b.target);
    const expectedFields=response===undefined?{}:Object.fromEntries(fields(response).filter(f=>!dynamic.some(p=>f.path===p||f.path.startsWith(p+'/'))&&!/password|secret|token|authorization|cookie|api.?key/i.test(f.path)).map(f=>[f.path,f.value]));
